  /** True if 2Z moved for the request this body describes. False means it was absorbed as a duplicate of a very recent one; the fan is subscribed either way. On an Idempotency-Key replay this still describes the ORIGINAL call, so do not decrement cached 2Z again on seeing it. */
  charged: boolean;
  /** Membership end date as of this request. Use it rather than assuming the previous value plus 30 days. On an Idempotency-Key replay it is the value recorded then and a later renewal may have pushed it out since, so refresh from my-subscriptions instead of writing a replayed value over current state. */
  expires: string;
  /** True when this is the replay of a completed Idempotency-Key request rather than a new subscription attempt. */
  replayed: boolean;
