export type TuzisSubscribeCreate400 = {
  error: string;
  /** Present as `invalid_idempotency_key` when an Idempotency-Key header was sent but is not a canonical UUIDv4. Nothing was charged; do NOT discard the key and mint another on a retry -- check my-subscriptions first, because the original request under that key may have completed. */
  code?: string;
};

export type TuzisSubscribeCreate409 = {
  error: string;
  /** `idempotency_mismatch` when this key is already spent on a different request for THIS creator -- including one made on POST /api/tuzis/subscribe-confirmed/{username}/, whose keys share this namespace, or one recorded there before  added the recipient id and so no longer attributable to a creator at all. A confirmed receipt that is positively another creator's is not this request and is charged normally under this route's per-creator scope. It also covers a key spent on a membership that has since ENDED, on either route: that receipt is real, but the month it bought is over, so it is neither replayed (you are not subscribed) nor charged again under the same key -- `key_resolved: true` says to retire it and buy under a fresh one. `invalid_idempotency_record` when a receipt exists but cannot be replayed safely -- a stored body this route cannot read, or one with no membership recorded at all. Absent on the in-flight answer. `subscription_retryable` means a lock timeout left the request undecided; reuse the SAME Idempotency-Key. `subscription_intent_abandoned` means authenticated recovery fenced this key; retire it and use a fresh key for a deliberate new purchase. */
  code?: string;
  /** Only on `idempotency_mismatch`, and only when this endpoint can prove it: true means the request recorded under your Idempotency-Key has FINISHED and cannot be the one you are making now -- another creator's, or a membership that has since ended -- so retire that key and mint a new one. It is NOT merely "a different request finished": a finished receipt for a membership you are still holding is your own purchase and replays as a 200 instead, because retiring the key there would buy a second month. False means it may still be committing -- reuse the SAME key. Absent means the endpoint could not tell (a receipt it cannot attribute), which is also a reason to reuse the same key. Without this a client that keeps one key per purchase intent can be answered 409 for the receipt's whole retention horizon with no way to recover. */
  key_resolved?: boolean;
};

